def split(ds: Any, partition: Any) -> object {
    n_data = len(ds);
    partition = [int(((n_data * x) / sum(partition))) for x in partition];
    ds_batched = [];
    idx = 0;
    for p_size in partition {
        ds_batched.append(ds[idx:(idx + p_size)]);
        idx += p_size;
    }
    return ds_batched;
}

"""Remove prefix `start` from sting `s`. Raises a :py:exc:`ValueError`
    if `s` didn't start with `start`."""
def drop_prefix(s: Any, start: Any) -> object {
    l = len(start);
    if (s[:l] != start) {
        raise ValueError('string does not start with expected value');
    }
    return s[l:];
}

"""Convert index from flattened upper triangular matrix to pair subindex.

    Parameters
    ----------
    n : int
        Dimension size of square array.
    ix : int
        Index to convert.

    Returns
    -------
    subix : tuple
        (i,j)
    """
def ind_to_sub(n: Any, ix: Any) -> object {
    k = 0;
    for i in range((n - 1)) {
        for j in range((i + 1), n) {
            if (k == ix) {
                return (i, j);
            }
            k += 1;
        }
    }
}

